-- 0001_init: agents, conversations, runs, messages, tool_calls.
-- IDs are text UUIDs generated by Postgres so Go code can treat them as plain strings.

CREATE TABLE agents (
    id            TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,
    name          TEXT        NOT NULL CHECK (name <> ''),
    system_prompt TEXT        NOT NULL DEFAULT '',
    model         TEXT        NOT NULL DEFAULT '',
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at    TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE conversations (
    id         TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,
    agent_id   TEXT        NOT NULL REFERENCES agents (id) ON DELETE CASCADE,
    title      TEXT        NOT NULL DEFAULT '',
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX conversations_agent_idx ON conversations (agent_id, created_at DESC);

CREATE TABLE runs (
    id              TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,
    conversation_id TEXT        NOT NULL REFERENCES conversations (id) ON DELETE CASCADE,
    status          TEXT        NOT NULL DEFAULT 'running'
                    CHECK (status IN ('running', 'completed', 'failed')),
    stop_reason     TEXT        NOT NULL DEFAULT '',
    error           TEXT        NOT NULL DEFAULT '',
    model           TEXT        NOT NULL DEFAULT '',
    input_tokens    BIGINT      NOT NULL DEFAULT 0,
    output_tokens   BIGINT      NOT NULL DEFAULT 0,
    iterations      INTEGER     NOT NULL DEFAULT 0,
    started_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    finished_at     TIMESTAMPTZ
);

CREATE INDEX runs_conversation_idx ON runs (conversation_id, started_at DESC);

CREATE TABLE messages (
    id              TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,
    seq             BIGINT GENERATED ALWAYS AS IDENTITY,
    conversation_id TEXT        NOT NULL REFERENCES conversations (id) ON DELETE CASCADE,
    run_id          TEXT        REFERENCES runs (id) ON DELETE SET NULL,
    role            TEXT        NOT NULL CHECK (role IN ('user', 'assistant')),
    content         TEXT        NOT NULL,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX messages_conversation_seq_idx ON messages (conversation_id, seq);

CREATE TABLE tool_calls (
    id          TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,
    seq         BIGINT GENERATED ALWAYS AS IDENTITY,
    run_id      TEXT        NOT NULL REFERENCES runs (id) ON DELETE CASCADE,
    name        TEXT        NOT NULL,
    input       JSONB       NOT NULL DEFAULT '{}'::jsonb,
    output      TEXT        NOT NULL DEFAULT '',
    is_error    BOOLEAN     NOT NULL DEFAULT false,
    duration_ms INTEGER     NOT NULL DEFAULT 0,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX tool_calls_run_seq_idx ON tool_calls (run_id, seq);
